package io.github.krushnatkhawale.blogify.core.parser;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Properties;

/**
 * Metadata loaded from an optional 'blogify.info' or 'plugin.info' properties file.
 * Typically generated by LLMs or authored alongside blog bundles to configure site title,
 * release version, author, date, and taxonomy without editing build scripts.
 */
public class BlogifyMetadata {

    private final Properties properties = new Properties();

    public BlogifyMetadata() {
    }

    public BlogifyMetadata(Properties props) {
        if (props != null) {
            this.properties.putAll(props);
        }
    }

    public static BlogifyMetadata fromFile(File file) {
        BlogifyMetadata meta = new BlogifyMetadata();
        if (file != null && file.exists() && file.isFile()) {
            try (InputStream in = new FileInputStream(file)) {
                meta.properties.load(in);
            } catch (IOException ignored) {
            }
        }
        return meta;
    }

    public static BlogifyMetadata findInDirectory(File dir) {
        if (dir == null || !dir.exists()) {
            return new BlogifyMetadata();
        }

        File blogifyInfo = new File(dir, "blogify.info");
        if (blogifyInfo.exists()) {
            return fromFile(blogifyInfo);
        }

        File pluginInfo = new File(dir, "plugin.info");
        if (pluginInfo.exists()) {
            return fromFile(pluginInfo);
        }

        // Also check if any child directory has a blogify.info (e.g. blogs/<topic>/blogify.info)
        File[] children = dir.listFiles(File::isDirectory);
        if (children != null) {
            for (File child : children) {
                File childInfo = new File(child, "blogify.info");
                if (childInfo.exists()) {
                    return fromFile(childInfo);
                }
                File childPluginInfo = new File(child, "plugin.info");
                if (childPluginInfo.exists()) {
                    return fromFile(childPluginInfo);
                }
            }
        }

        return new BlogifyMetadata();
    }

    public boolean isEmpty() {
        return properties.isEmpty();
    }

    public String getProperty(String... keys) {
        for (String k : keys) {
            String val = properties.getProperty(k);
            if (val != null && !val.trim().isBlank()) {
                return val.trim();
            }
        }
        return "";
    }

    public String getSiteTitle() {
        return getProperty("siteTitle", "site_title", "title", "blogTitle", "blog_title");
    }

    public String getVersion() {
        return getProperty("version", "releaseVersion", "release_version");
    }

    public String getAuthor() {
        return getProperty("author", "writer");
    }

    public String getDate() {
        return getProperty("date", "publishedDate", "published_date");
    }

    public String getCategory() {
        return getProperty("category", "topic");
    }

    public String getDescription() {
        return getProperty("description", "summary");
    }

    public String getSlug() {
        return getProperty("slug");
    }

    public List<String> getTags() {
        String tagsStr = getProperty("tags", "tag");
        if (!tagsStr.isBlank()) {
            return Arrays.stream(tagsStr.split(","))
                    .map(String::trim)
                    .filter(s -> !s.isBlank())
                    .toList();
        }
        return Collections.emptyList();
    }
}
